CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(160) UNIQUE,password_hash VARCHAR(255),role VARCHAR(50) DEFAULT 'ventas',active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY,`value` TEXT);
CREATE TABLE IF NOT EXISTS clients (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),phone VARCHAR(30),email VARCHAR(160),city VARCHAR(120),address TEXT,source VARCHAR(120),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads (id INT AUTO_INCREMENT PRIMARY KEY,client_id INT NULL,client_name VARCHAR(160),phone VARCHAR(30),product VARCHAR(120),stage VARCHAR(80),amount DECIMAL(12,2) DEFAULT 0,source VARCHAR(120),next_followup DATE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes (id INT AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(40) UNIQUE,client_id INT NULL,client_name VARCHAR(160),phone VARCHAR(30),project VARCHAR(160),description TEXT,delivery_time VARCHAR(120),subtotal DECIMAL(12,2) DEFAULT 0,discount DECIMAL(12,2) DEFAULT 0,total DECIMAL(12,2) DEFAULT 0,advance DECIMAL(12,2) DEFAULT 0,status VARCHAR(40) DEFAULT 'Emitida',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts (id INT AUTO_INCREMENT PRIMARY KEY,folio VARCHAR(40) UNIQUE,quote_id INT,client_name VARCHAR(160),amount DECIMAL(12,2),payment_method VARCHAR(80),concept TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY,quote_id INT NULL,name VARCHAR(160),client_name VARCHAR(160),product VARCHAR(120),status VARCHAR(80) DEFAULT 'Diseño',progress INT DEFAULT 0,delivery_date DATE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory (id INT AUTO_INCREMENT PRIMARY KEY,item VARCHAR(160),unit VARCHAR(40),stock DECIMAL(12,2) DEFAULT 0,min_stock DECIMAL(12,2) DEFAULT 0,cost DECIMAL(12,2) DEFAULT 0,supplier VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses (id INT AUTO_INCREMENT PRIMARY KEY,concept VARCHAR(180),amount DECIMAL(12,2),category VARCHAR(100),expense_date DATE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180),event_type VARCHAR(80),event_date DATE,client_name VARCHAR(160),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
